def comps_conn(a,diag=False):
 R,C=len(a),len(a[0]);seen=set();ans=[]
 ds=[(1,0),(-1,0),(0,1),(0,-1)]
 if diag: ds += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(R):
  for c in range(C):
   if a[r][c]==0 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));cc=[]
    for x,y in q:
     cc.append((x,y))
     for dx,dy in ds:
      xx,yy=x+dx,y+dy
      if 0<=xx<R and 0<=yy<C and a[xx][yy]==0 and (xx,yy) not in seen:seen.add((xx,yy));q.append((xx,yy))
    ans.append(cc)
 return sorted(ans,key=len,reverse=True)
for i,a in enumerate([D1,D2,D3]):
 print('demo',i+1)
 for cc in comps_conn(a,True): print(len(cc), (min(x for x,y in cc),max(x for x,y in cc),min(y for x,y in cc),max(y for x,y in cc)), 'touch',any(x in [0,len(a)-1] or y in [0,len(a[0])-1] for x,y in cc))
